var jsonl={parse:function(t){var n=t.trim();if(!n)return[];var e=n.split("\n"),i=[];for(var s=0;s<e.length;s++){var o=e[s].trim();if(o)try{i.push(JSON.parse(o))}catch(u){throw new Error("Invalid JSON at line "+(s+1))}}return i},stringify:function(t){var n=[];for(var e=0;e<t.length;e++)n.push(JSON.stringify(t[e]));return n.join("\n")}};